<section class="catalog-admin-page"><div class="admin-page-heading"><span>Back-office</span><h1>Gestion du catalogue</h1><p>Publiez les catégories et produits canoniques qui alimenteront la marketplace.</p></div><?php if ($message): ?><div class="catalog-admin-message"><?= e($message) ?></div><?php endif; ?><?php if (! empty($errors)): ?><div class="catalog-admin-error"><?= e((string) ($errors[array_key_first($errors)][0] ?? 'Une erreur est survenue.')) ?></div><?php endif; ?><div class="catalog-admin-grid"><form class="catalog-admin-form" action="<?= e(url('admin/catalogue/categories')) ?>" method="post"><h2>Nouvelle categorie</h2><?= csrf_field() ?><label for="category-name">Nom</label><input id="category-name" name="name" required><label for="category-description">Description</label><textarea id="category-description" name="description"></textarea><button type="submit">Créer la categorie</button></form><form class="catalog-admin-form" action="<?= e(url('admin/catalogue/produits')) ?>" method="post"><h2>Nouveau produit</h2><?= csrf_field() ?><label for="product-name">Nom</label><input id="product-name" name="name" required><label for="product-category">Categorie</label><select id="product-category" name="category_slug" required><?php foreach ($categories as $category): ?><option value="<?= e($category['slug']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select><label for="product-short-description">Description courte</label><input id="product-short-description" name="short_description"><label for="product-description">Description</label><textarea id="product-description" name="description"></textarea><label class="checkbox-label"><input type="checkbox" name="requires_prescription" value="1"> Necessite une ordonnance</label><button type="submit">Publier le produit</button></form></div><div class="catalog-admin-list"><h2>Produits publies</h2><?php foreach ($products as $product): ?><div><strong><?= e($product['name']) ?></strong><span><?= e($product['category_name']) ?></span><a href="<?= e(url('produit/' . $product['slug'])) ?>">Voir</a></div><?php endforeach; ?></div></section>